export const RAW_LEVELS: LevelDefinition[] = [...ORIGINAL_LEVELS, ...EXPANSION_LEVELS, ...THIRD_JOURNEY_LEVELS];

/**
 * Yeni bir bölümü yalnızca harf havuzu ve hedef kelime listesiyle kolayca oluşturup
 * otomatik olarak kompakt yerleşim üreterek doğrulamaya yarar.
 */
export function createAutoLevel(spec: RawLevelSpec): LevelDefinition {
  const layout = generateCompactCrosswordLayout(spec.targetWords);
  if (!layout) {
    throw new Error(
      `[Kelime Yolculuğu] Bölüm ${spec.id} için geçerli bulmaca yerleşimi üretilemedi.`
    );
  }
  const level: LevelDefinition = {
    id: spec.id,
    theme: spec.theme,
    letters: spec.letters.map(toTurkishUpper),
    words: layout,
    rewardCoins: spec.rewardCoins,
    ...(spec.isRestLevel ? { isRestLevel: true } : {}),
  };
  const check = validateLevel(level);
  if (!check.valid) {
    throw new Error(
      `[Kelime Yolculuğu] Bölüm ${spec.id} doğrulama hatası:\n - ${check.errors.join('\n - ')}`
    );
  }
  return level;
}

// Başlangıçta tüm bölümleri otomatik doğrula; hatalı bölüm verisini oyuncuya kesinlikle açma
export const LEVEL_VALIDATION_REPORT = validateAllLevels(RAW_LEVELS);

if (LEVEL_VALIDATION_REPORT.invalidResults.length > 0) {
  const details = LEVEL_VALIDATION_REPORT.invalidResults
    .map((r) => `Bölüm ${r.levelId}: ${r.errors.join(' | ')}`)
    .join('\n');
  console.error(
    `[Kelime Yolculuğu] Doğrulamadan geçemeyen bölümler tespit edildi ve engellendi:\n${details}`
  );
  if (import.meta.env.DEV) {
    throw new Error(`[Kelime Yolculuğu] Hatalı bölüm verisi tespit edildi!\n${details}`);
  }
}

export const LEVELS: readonly LevelDefinition[] = LEVEL_VALIDATION_REPORT.validLevels;

export function getLevelById(id: number): LevelDefinition | undefined {
  return LEVELS.find((lvl) => lvl.id === id);
}
